            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    if not all(is_valid_parentheses(s) for s in lst):
        return 'No'

    concatenated = ''.join(lst)

    if is_balanced(concatenated):
        return 'Yes'
    else:
        return 'No'

